import {afterWrite,readRecord,MAX_IDEMPOTENCY_RECORD_BYTES as cap} from '@/lib/api-idempotency-rules';
import {is,done} from '@/tests/check';
const fp='a'.repeat(64),at=Date.UTC(2026,10,10);
const priorBody=JSON.stringify({value:'"'.repeat(3998)});
is('same prior 8008-byte response size',Buffer.byteLength(priorBody),8008);
is('quoted response exceeding serialized cap holds claim',afterWrite(fp,at,200,priorBody,'done').action,'hold');
is('control-character escaping also holds claim',afterWrite(fp,at,200,'\u0000'.repeat(8192),'done').action,'hold');
for(const body of ['a'.repeat(8192),'é'.repeat(4096),'😀'.repeat(2048)]){
 const r=afterWrite(fp,at,200,body,'done');
 is('fitting 8192-byte answer kept',r.action,'keep');
 is('serialized kept record is bounded',r.action==='keep'&&Buffer.byteLength(r.record)<=cap,true);
 is('kept record reads back exactly',r.action==='keep'?readRecord(r.record)?.body:null,body);
}
const fixed={state:'done',fp,at,status:200,body:''};
const overhead=Buffer.byteLength(JSON.stringify(fixed));
for(const extra of [0,1]){
 const raw=JSON.stringify({...fixed,body:'a'.repeat(cap-overhead+extra)});
 is('exact byte-boundary setup',Buffer.byteLength(raw),cap+extra);
 is('reader accepts exact cap only',readRecord(raw)!==null,extra===0);
}
const raw=JSON.stringify({...fixed,body:'é'.repeat(4300)});
is('multibyte record can be under cap in chars but over in bytes',raw.length<cap&&Buffer.byteLength(raw)>cap,true);
is('reader refuses oversized UTF8 bytes',readRecord(raw),null);
done();

